"use client";

import React, { useState, useRef, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Send, Sparkles, Bot, User } from "lucide-react";

const BusinessNameGenerator = () => {
  const [messages, setMessages] = useState([
    { type: "bot", content: "Hi there! I'm your AI assistant. How can I help you with business naming today?" }
  ]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!inputValue.trim()) return;

    // Add user message
    setMessages(prev => [...prev, { type: "user", content: inputValue }]);
    
    // Clear input and show loading state
    setInputValue("");
    setIsLoading(true);
    
    // Simulate AI response for business naming
    setTimeout(() => {
      setMessages(prev => [...prev, { 
        type: "bot", 
        content: "Here are some business name suggestions based on your input: 'InnovateX', 'Prime Solutions', 'Nexus Ventures'. Would you like me to generate more options or refine these?"
      }]);
      setIsLoading(false);
    }, 1000);
  };

  return (
    <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
      <div className="flex flex-col items-center text-center mb-12">
        <h2 className="text-3xl md:text-4xl font-bold mb-4">Business Name Generator</h2>
        <p className="text-gray-600 max-w-2xl">
          Get AI-powered suggestions for your perfect business name. Describe your business or industry to get started.
        </p>
      </div>

      <div className="max-w-3xl mx-auto w-full bg-gray-50 rounded-2xl shadow-lg overflow-hidden">
        {/* Chat messages area */}
        <div className="h-96 overflow-y-auto p-6 flex flex-col gap-4">
          {messages.map((message, index) => (
            <div 
              key={index} 
              className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div className={`flex gap-3 max-w-[80%] ${message.type === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
                  message.type === 'user' ? 'bg-black text-white' : 'bg-gray-200'
                }`}>
                  {message.type === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className={`py-3 px-4 rounded-2xl ${
                  message.type === 'user' 
                    ? 'bg-black text-white rounded-tr-none' 
                    : 'bg-white border border-gray-200 rounded-tl-none'
                }`}>
                  {message.content}
                </div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="flex gap-3 max-w-[80%]">
                <div className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 bg-gray-200">
                  <Bot size={16} />
                </div>
                <div className="py-3 px-6 rounded-2xl bg-white border border-gray-200 rounded-tl-none">
                  <div className="flex gap-1">
                    <div className="w-2 h-2 rounded-full bg-gray-400 animate-bounce"></div>
                    <div className="w-2 h-2 rounded-full bg-gray-400 animate-bounce" style={{animationDelay: '0.2s'}}></div>
                    <div className="w-2 h-2 rounded-full bg-gray-400 animate-bounce" style={{animationDelay: '0.4s'}}></div>
                  </div>
                </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input area */}
        <div className="border-t border-gray-200 p-4">
          <form onSubmit={handleSubmit} className="flex gap-2">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Describe your business for name suggestions..."
              className="flex-1 py-3 px-4 rounded-full border border-gray-300 focus:outline-none focus:ring-2 focus:ring-black"
              disabled={isLoading}
            />
            <Button 
              type="submit" 
              className="rounded-full bg-black text-white px-4 h-12 font-medium hover:bg-gray-800 transition-colors"
              disabled={isLoading || !inputValue.trim()}
            >
              <Send size={20} className="mr-0 md:mr-2" />
              <span className="hidden md:inline">Generate Names</span>
            </Button>
          </form>
          
          <div className="mt-4 flex flex-wrap gap-2">
            <Button
              onClick={() => {
                setInputValue("I need a tech startup name");
              }}
              variant="outline"
              className="rounded-full border border-gray-300 text-gray-700 text-sm py-1 px-4 flex items-center gap-1 hover:bg-gray-100"
            >
              <Sparkles size={14} /> Tech Startup
            </Button>
            <Button
              onClick={() => {
                setInputValue("Suggest names for a coffee shop");
              }}
              variant="outline"
              className="rounded-full border border-gray-300 text-gray-700 text-sm py-1 px-4 flex items-center gap-1 hover:bg-gray-100"
            >
              <Sparkles size={14} /> Coffee Shop
            </Button>
            <Button
              onClick={() => {
                setInputValue("Creative names for a marketing agency");
              }}
              variant="outline"
              className="rounded-full border border-gray-300 text-gray-700 text-sm py-1 px-4 flex items-center gap-1 hover:bg-gray-100"
            >
              <Sparkles size={14} /> Marketing Agency
            </Button>
          </div>
        </div>
      </div>
    </section>
  );
};

export default BusinessNameGenerator;